        public static readonly Dictionary<string, Dictionary<string, string>> Loc = new Dictionary<string, Dictionary<string, string>>
        {
                ["de-DE"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Fahrgäste hier", ["ui.ruleBoth"]="normal", ["ui.ruleDropOff"]="nur Ausstieg", ["ui.rulePickUp"]="nur Einstieg", ["ui.ruleTechnical"]="Betriebshalt", ["ui.ruleTechnicalNote"]="Hier darf niemand an Bord sein: Der letzte Ausstieg ist die vorherige Haltestelle. Keine Fahrt auf dieser Linie kann diese Haltestelle passieren, und Fahrzeuge halten immer.", ["ui.ruleOrphan"]="Für diese Linie sind Ein-/Ausstiegsregeln an {n} Haltestelle(n) festgelegt, die nicht mehr auf ihrer Strecke liegen, daher werden sie nicht angewendet.", ["ui.ruleOrphanRemove"]="Entfernen",["ui.arrives"]="Ankunft: {d}", ["ui.layoverClear"]="entfernen", ["ui.setLayoverThis"]="Als Endhaltestelle B festlegen", ["opt.ManageVehicleCount.L"]="Fahrzeuganzahl verwalten", ["opt.CleanUninstall.L"]="Alle Mod-Daten aus diesem Spielstand entfernen", ["opt.RealisticTravelTime.L"]="Realistische Fahrzeit (korrigiert angezeigte Zeiten)", ["opt.RealisticTravelTime.D"]="Die spieleigene Schätzung, wie lange eine Linie braucht, liegt unter dem echten, simulierten Umlauf — Busse beschleunigen und bremsen an jeder Haltestelle, was die Schätzung ignoriert (live gemessen etwa 1,7x auf dünnen Linien bis ~2,5x auf haltestellendichten). Aktiviere dies, und der Mod misst den echten Umlauf jeder Linie und trägt realistische Haltezeiten ein, sodass der Fahrplan dem entspricht, was die Busse tatsächlich tun. Kostet nichts — es macht die Uhr nur ehrlich. Standardmäßig AUS; bestehende Fahrpläne bleiben unverändert, bis du es aktivierst.", ["opt.ProvisionRealFleet.L"]="Fuhrpark an reale Fahrzeit anpassen (erhöht die Fahrzeuganzahl)", ["opt.ProvisionRealFleet.D"]="Bemisst außerdem die Fahrzeuganzahl jeder Linie an ihrem ECHTEN Umlauf statt an der Schätzung. Dies ist die Option, die Geld kostet: einen engen Takt auf einer Linie zu halten, deren echter Umlauf ~2x der Schätzung beträgt, benötigt etwa doppelt so viele Fahrzeuge und doppelten Unterhalt. AUS (Standard) behält die schätzungsbasierte Anzahl, sodass eine Linie unbemerkt einen längeren effektiven Takt fährt als eingestellt; AN legt für den echten Umlauf aus. Nur aufstockend — es senkt eine Linie nie unter die Schätzung — und begrenzt, damit eine fehlerhafte Messung dich nicht mit Bussen überflutet.", ["ui.loopMeasuring"]="Die tatsächliche Umlaufzeit wird noch gemessen ({laps} von {need} Runden).", ["ui.loopRefining"]="Tatsächliche Umlaufzeit etwa {real} Min., wird noch verfeinert ({wlaps} von {need2} Runden).", ["ui.loopMeasured"]="Tatsächliche Umlaufzeit {real} Min., gemessen ({corr}x der Schätzung von {est} Min.).", ["enum.VehicleCounts.HandsOff"]="Den Mod nicht entscheiden lassen", ["enum.VehicleCounts.ModDecides"]="Den Mod entscheiden lassen", ["opt.VehicleCounts.L"]="Fahrzeuganzahl", ["opt.VehicleCounts.D"]="Wer entscheidet, wie viele Fahrzeuge auf jeder Linie mit Fahrplan fahren. \"Den Mod entscheiden lassen\" (empfohlen) bemisst jede Linie anhand der gemessenen echten Fahrdauer, damit sie den eingestellten Takt tatsächlich halten kann, und erfordert keine Aufmerksamkeit. In diesem Modus bestimmt der Mod die Anzahl auf jeder Linie mit Fahrplan: Der spieleigene Regler für zugewiesene Fahrzeuge bleibt nicht erhalten, da der Mod seinen eigenen Wert erneut anwendet. \"Den Mod nicht entscheiden lassen\" gibt jede Linie zurück und rührt die Anzahl nie wieder an, sodass du oder ein spezialisierter Fuhrpark-Mod sie übernehmen kann. Das Halten bis zur Abfahrtszeit funktioniert in beiden Fällen gleich. Wenn eine Linie mehr Fahrzeuge verlangt, als du möchtest, vergrößere ihren Takt; das ist die eigentliche Stellschraube.", ["opt.StopAtEveryStop.L"]="An jeder Haltestelle halten (auch an leeren)", ["opt.RealisticTripsCompat.L"]="Realistic Trips / Zeitlupen-Kompatibilität — AN, wenn du RT oder Time2Work nutzt (ALPHA)", ["opt.RealisticTripsCompat.D"]="Standardmäßig AUS — lass es aus, außer du nutzt einen Mod, der den Spieltag verlängert (Time2Work / \"Realistic Trips\" oder ähnlich). Aktiviere es mit einem solchen Mod, und Abfahrten, Haltezeiten und Flottengrößen bleiben korrekt, statt zu früh zu laufen; der Mod misst die echte Taglänge automatisch. Ohne Zeitlupen-Mod bewirkt diese Einstellung nichts, und erkennt der Mod einen solchen, während dies AUS ist, vermerkt er es im Log. HINWEIS: Dieser Kompatibilitätspfad ist ALPHA und wurde noch NICHT im Spiel mit Realistic Trips getestet — bitte melde alles Auffällige. Unter Realistic Trips nutzen deine Linien korrekterweise weniger Fahrzeuge als zuvor.", ["opt.MorningPeakStart.L"]="Beginn der Morgenspitze", ["opt.MorningPeakStart.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit beginnt.", ["opt.MorningPeakEnd.L"]="Ende der Morgenspitze", ["opt.MorningPeakEnd.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit endet.", ["opt.EveningPeakStart.L"]="Beginn der Abendspitze", ["opt.EveningPeakStart.D"]="Stunde, zu der die abendliche Hauptverkehrszeit beginnt.", ["opt.EveningPeakEnd.L"]="Ende der Abendspitze", ["opt.EveningPeakEnd.D"]="Stunde, zu der die abendliche Hauptverkehrszeit endet.", ["opt.NightStart.L"]="Nachtbeginn", ["opt.NightStart.D"]="Stunde, zu der der Nachtbetrieb beginnt (kann über Mitternacht hinausgehen).", ["opt.NightEnd.L"]="Nachtende", ["opt.NightEnd.D"]="Stunde, zu der der Nachtbetrieb endet.", ["opt.Enabled.L"]="TransitTimetables aktivieren", ["grp.GroupWindows"]="Hauptverkehrszeiten", ["grp.GroupCompat"]="Kompatibilität", ["grp.GroupStops"]="Haltestellen", ["grp.GroupGeneral"]="Allgemein", ["ui.to"]="bis", ["ui.on"]="AN", ["ui.off"]="AUS", ["ui.otherHours"]="übrige Stunden", ["ui.customLinePeak"]="Eigene Spitze (diese Linie)", ["ui.morningPeak"]="Morgenspitze", ["ui.eveningPeak"]="Abendspitze", ["ui.noLines"]="Keine Linien bedienen diese Haltestelle.", ["ui.line"]="Linie {n}", ["ui.terminusBadge"]="Endhaltestelle", ["ui.setTerminusThis"]="Als Endhaltestelle festlegen", ["ui.setTerminusAll"]="Als Endhaltestelle für alle Linien hier festlegen", ["ui.buttonTooltip"]="Transit Timetables" },
                ["es-ES"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Pasajeros aquí", ["ui.ruleBoth"]="normal", ["ui.ruleDropOff"]="solo bajada", ["ui.rulePickUp"]="solo subida", ["ui.ruleTechnical"]="parada técnica", ["ui.ruleTechnicalNote"]="Aquí nadie puede ir a bordo: la última parada para bajar es la anterior. Ningún viaje de esta línea puede pasar esta parada, y los vehículos siempre paran.", ["ui.ruleOrphan"]="Esta línea tiene reglas de subida/bajada en {n} parada(s) que ya no están en su ruta, por lo que no se aplican.", ["ui.ruleOrphanRemove"]="Eliminarlas",["ui.arrives"]="llega: {d}", ["ui.layoverClear"]="quitar", ["ui.setLayoverThis"]="Fijar como terminal B", ["opt.ManageVehicleCount.L"]="Gestionar el número de vehículos", ["opt.CleanUninstall.L"]="Eliminar todos los datos del mod de esta partida", ["opt.RealisticTravelTime.L"]="Tiempo de viaje realista (corrige los horarios publicados)", ["opt.RealisticTravelTime.D"]="La propia estimación del juego sobre lo que tarda una línea se queda corta respecto al recorrido real simulado: los autobuses aceleran y frenan en cada parada, algo que la estimación ignora (medido en vivo, alrededor de 1,7x en líneas con pocas paradas y hasta ~2,5x en las de muchas paradas). Actívalo y el mod mide el recorrido real de cada línea y publica horarios de parada realistas, de modo que el panel coincida con lo que los autobuses hacen de verdad. No cuesta nada: solo hace que el reloj sea honesto. Desactivado por defecto; los horarios existentes no se modifican hasta que lo actives.", ["opt.ProvisionRealFleet.L"]="Dimensionar la flota según el tiempo de viaje real (aumenta el número de vehículos)", ["opt.ProvisionRealFleet.D"]="Dimensiona también el número de vehículos de cada línea a su recorrido REAL en lugar de a la estimación. Esta es la opción que gasta: mantener un intervalo ajustado en una línea cuyo recorrido real es ~2x la estimación requiere aproximadamente el doble de vehículos, y el doble de mantenimiento. Desactivado (por defecto) mantiene el recuento basado en la estimación, con lo que una línea funciona en silencio con un intervalo efectivo mayor del que fijaste; activado la dimensiona para el recorrido real. Solo crece —nunca reduce una línea por debajo de la estimación— y tiene un tope, de modo que una lectura errónea no puede inundarte de autobuses.", ["ui.loopMeasuring"]="El recorrido real aún se está midiendo ({laps} de {need} vueltas).", ["ui.loopRefining"]="Recorrido real de unos {real} min, aún ajustándose ({wlaps} de {need2} vueltas).", ["ui.loopMeasured"]="Recorrido real de {real} min, medido ({corr}x la estimación de {est} min).", ["enum.VehicleCounts.HandsOff"]="No dejar que decida el mod", ["enum.VehicleCounts.ModDecides"]="Dejar que decida el mod", ["opt.VehicleCounts.L"]="Número de vehículos", ["opt.VehicleCounts.D"]="Quién decide cuántos vehículos circulan en cada línea con horario. \"Dejar que decida el mod\" (recomendado) dimensiona cada línea midiendo lo que tarda realmente su recorrido, para que pueda mantener el intervalo que has fijado, y no requiere atención. En este modo el mod controla el número en todas las líneas con horario: el control de vehículos asignados del juego no se mantendrá, porque el mod vuelve a aplicar su propio valor. \"No dejar que decida el mod\" devuelve todas las líneas y no vuelve a tocar el número, de modo que tú o un mod de flotas dedicado podáis gestionarlo. Las esperas de salida funcionan igual en ambos casos. Si una línea pide más vehículos de los que quieres, amplía su intervalo; ese es el control real.", ["opt.StopAtEveryStop.L"]="Parar en todas las paradas (incluso las vacías)", ["opt.RealisticTripsCompat.L"]="Compatibilidad con Realistic Trips / tiempo lento — actívalo si usas RT o Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desactivado por defecto: déjalo así salvo que uses un mod que alargue el día del juego (Time2Work / \"Realistic Trips\" o similar). Actívalo con un mod de ese tipo y las salidas, los horarios de parada y el tamaño de la flota seguirán siendo correctos en lugar de adelantarse; el mod mide automáticamente la duración real del día. Sin un mod de tiempo lento, esta opción no hace nada, y si el mod detecta uno mientras esto está desactivado lo anotará en el registro. NOTA: esta vía de compatibilidad es ALFA y AÚN NO se ha probado con Realistic Trips en el juego; informa de cualquier anomalía. Con Realistic Trips, tus líneas usarán correctamente menos vehículos que antes.", ["opt.MorningPeakStart.L"]="Inicio de la hora punta de la mañana", ["opt.MorningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la mañana.", ["opt.MorningPeakEnd.L"]="Fin de la hora punta de la mañana", ["opt.MorningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la mañana.", ["opt.EveningPeakStart.L"]="Inicio de la hora punta de la tarde", ["opt.EveningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la tarde.", ["opt.EveningPeakEnd.L"]="Fin de la hora punta de la tarde", ["opt.EveningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la tarde.", ["opt.NightStart.L"]="Inicio de la noche", ["opt.NightStart.D"]="Hora en que empieza el servicio nocturno (puede pasar de la medianoche).", ["opt.NightEnd.L"]="Fin de la noche", ["opt.NightEnd.D"]="Hora en que termina el servicio nocturno.", ["opt.Enabled.L"]="Activar TransitTimetables", ["grp.GroupWindows"]="Franjas de hora punta", ["grp.GroupCompat"]="Compatibilidad", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="General", ["ui.to"]="a", ["ui.on"]="SÍ", ["ui.off"]="NO", ["ui.otherHours"]="otras horas", ["ui.customLinePeak"]="Hora punta personalizada (esta línea)", ["ui.morningPeak"]="Hora punta de la mañana", ["ui.eveningPeak"]="Hora punta de la tarde", ["ui.noLines"]="Ninguna línea da servicio a esta parada.", ["ui.line"]="Línea {n}", ["ui.terminusBadge"]="terminal", ["ui.setTerminusThis"]="Fijar como terminal", ["ui.setTerminusAll"]="Fijar como terminal para todas las líneas de aquí", ["ui.buttonTooltip"]="Horarios de transporte" },
                ["fr-FR"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Voyageurs ici", ["ui.ruleBoth"]="normal", ["ui.ruleDropOff"]="descente uniquement", ["ui.rulePickUp"]="montée uniquement", ["ui.ruleTechnical"]="arrêt technique", ["ui.ruleTechnicalNote"]="Personne ne peut être à bord ici : le dernier arrêt pour descendre est le précédent. Aucun trajet sur cette ligne ne peut franchir cet arrêt, et les véhicules s'y arrêtent toujours.", ["ui.ruleOrphan"]="Cette ligne a des règles de montée/descente définies à {n} arrêt(s) qui ne sont plus sur son itinéraire ; elles ne sont donc pas appliquées.", ["ui.ruleOrphanRemove"]="Les supprimer",["ui.arrives"]="arrivée : {d}", ["ui.layoverClear"]="supprimer", ["ui.setLayoverThis"]="Définir comme terminus B", ["opt.ManageVehicleCount.L"]="Gérer le nombre de véhicules", ["opt.CleanUninstall.L"]="Supprimer de cette sauvegarde toutes les données du mod", ["opt.RealisticTravelTime.L"]="Temps de trajet réaliste (corrige les horaires affichés)", ["opt.RealisticTravelTime.D"]="L'estimation du jeu de la durée d'une ligne sous-évalue la boucle réelle simulée — les bus accélèrent et freinent à chaque arrêt, ce que l'estimation ignore (mesuré en direct à environ 1,7x sur les lignes espacées, jusqu'à ~2,5x sur celles à arrêts rapprochés). Activez cette option et le mod mesure la boucle réelle de chaque ligne et affiche des horaires d'arrêt réalistes, pour que le tableau corresponde à ce que font vraiment les bus. Ne coûte rien — cela rend simplement l'horloge honnête. Désactivé par défaut ; les horaires existants restent inchangés jusqu'à ce que vous l'activiez.", ["opt.ProvisionRealFleet.L"]="Dimensionner la flotte selon le temps de trajet réel (augmente le nombre de véhicules)", ["opt.ProvisionRealFleet.D"]="Dimensionne aussi le nombre de véhicules de chaque ligne d'après sa boucle RÉELLE plutôt que d'après l'estimation. C'est l'option qui dépense : maintenir un intervalle serré sur une ligne dont la boucle réelle fait ~2x l'estimation demande environ deux fois plus de véhicules, et deux fois plus d'entretien. Désactivé (par défaut) conserve le nombre basé sur l'estimation, donc une ligne applique en silence un intervalle effectif plus long que celui que vous avez réglé ; activé dimensionne pour la boucle réelle. Croissance uniquement — ne réduit jamais une ligne en dessous de l'estimation — et plafonné, pour qu'une mauvaise mesure ne vous inonde pas de bus.", ["ui.loopMeasuring"]="La boucle réelle est encore en cours de mesure ({laps} sur {need} tours).", ["ui.loopRefining"]="Boucle réelle d'environ {real} min, en cours d'affinage ({wlaps} sur {need2} tours).", ["ui.loopMeasured"]="Boucle réelle de {real} min, mesurée ({corr}x l'estimation de {est} min).", ["enum.VehicleCounts.HandsOff"]="Ne pas laisser le mod décider", ["enum.VehicleCounts.ModDecides"]="Laisser le mod décider", ["opt.VehicleCounts.L"]="Nombre de véhicules", ["opt.VehicleCounts.D"]="Qui décide du nombre de véhicules de chaque ligne avec horaires. \"Laisser le mod décider\" (recommandé) dimensionne chaque ligne en mesurant la durée réelle de son parcours, afin qu'elle puisse tenir l'intervalle que vous avez fixé, et ne demande aucune attention. Dans ce mode, le mod contrôle le nombre sur toutes les lignes avec horaires : le curseur de véhicules affectés du jeu ne sera pas conservé, car le mod réapplique sa propre valeur. \"Ne pas laisser le mod décider\" rend toutes les lignes et ne touche plus jamais au nombre, pour que vous ou un mod de flotte dédié puissiez le gérer. L'attente au départ fonctionne de la même façon dans les deux cas. Si une ligne demande plus de véhicules que vous ne le souhaitez, élargissez son intervalle ; c'est le véritable réglage.", ["opt.StopAtEveryStop.L"]="S'arrêter à chaque arrêt (même vides)", ["opt.RealisticTripsCompat.L"]="Compatibilité Realistic Trips / temps ralenti — activez si vous utilisez RT ou Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Désactivé par défaut — laissez-le désactivé sauf si vous utilisez un mod qui allonge la journée en jeu (Time2Work / \\\"Realistic Trips\\\" ou similaire). Activez-le avec un tel mod et les départs, horaires d'arrêt et tailles de flotte restent corrects au lieu d'être en avance ; le mod mesure automatiquement la durée réelle de la journée. Sans mod de temps ralenti ce réglage ne fait rien, et si le mod en détecte un alors que ceci est désactivé il le signalera dans le journal. NOTE : ce chemin de compatibilité est en ALPHA et n'a PAS encore été testé en jeu avec Realistic Trips — merci de signaler tout comportement étrange. Sous Realistic Trips vos lignes utiliseront correctement moins de véhicules qu'auparavant.", ["opt.MorningPeakStart.L"]="Début de la pointe du matin", ["opt.MorningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du matin.", ["opt.MorningPeakEnd.L"]="Fin de la pointe du matin", ["opt.MorningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du matin.", ["opt.EveningPeakStart.L"]="Début de la pointe du soir", ["opt.EveningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du soir.", ["opt.EveningPeakEnd.L"]="Fin de la pointe du soir", ["opt.EveningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du soir.", ["opt.NightStart.L"]="Début de nuit", ["opt.NightStart.D"]="Heure à laquelle commence le service de nuit (peut passer minuit).", ["opt.NightEnd.L"]="Fin de nuit", ["opt.NightEnd.D"]="Heure à laquelle se termine le service de nuit.", ["opt.Enabled.L"]="Activer TransitTimetables", ["grp.GroupWindows"]="Plages de pointe", ["grp.GroupCompat"]="Compatibilité", ["grp.GroupStops"]="Arrêts", ["grp.GroupGeneral"]="Général", ["ui.to"]="à", ["ui.on"]="ACTIVÉ", ["ui.off"]="DÉSACTIVÉ", ["ui.otherHours"]="autres heures", ["ui.customLinePeak"]="Pointe personnalisée (cette ligne)", ["ui.morningPeak"]="Pointe du matin", ["ui.eveningPeak"]="Pointe du soir", ["ui.noLines"]="Aucune ligne ne dessert cet arrêt.", ["ui.line"]="Ligne {n}", ["ui.terminusBadge"]="terminus", ["ui.setTerminusThis"]="Définir comme terminus", ["ui.setTerminusAll"]="Définir comme terminus pour toutes les lignes ici", ["ui.buttonTooltip"]="Horaires de transport" },
                ["it-IT"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Passeggeri qui", ["ui.ruleBoth"]="normale", ["ui.ruleDropOff"]="solo discesa", ["ui.rulePickUp"]="solo salita", ["ui.ruleTechnical"]="fermata tecnica", ["ui.ruleTechnicalNote"]="Qui nessuno può essere a bordo: l'ultima fermata per scendere è quella precedente. Nessun viaggio su questa linea può superare questa fermata e i veicoli fermano sempre.", ["ui.ruleOrphan"]="Questa linea ha regole di salita/discesa impostate su {n} fermata/e che non sono più sul suo percorso, quindi non vengono applicate.", ["ui.ruleOrphanRemove"]="Rimuovile",["ui.arrives"]="arriva: {d}", ["ui.layoverClear"]="rimuovi", ["ui.setLayoverThis"]="Imposta come capolinea B", ["opt.ManageVehicleCount.L"]="Gestisci il numero di veicoli", ["opt.CleanUninstall.L"]="Rimuovi tutti i dati della mod da questo salvataggio", ["opt.RealisticTravelTime.L"]="Tempo di percorrenza realistico (corregge gli orari esposti)", ["opt.RealisticTravelTime.D"]="La stima del gioco sulla durata di una linea è inferiore al percorso reale simulato: gli autobus accelerano e frenano a ogni fermata, cosa che la stima ignora (misurato dal vivo a circa 1,7x sulle linee con poche fermate, fino a ~2,5x su quelle con molte fermate). Attiva questa opzione e la mod misura il giro reale di ogni linea ed espone orari di fermata realistici, così il tabellone corrisponde a ciò che gli autobus fanno davvero. Non costa nulla: rende soltanto onesto l'orologio. Disattivata per impostazione predefinita; gli orari esistenti restano invariati finché non la abiliti.", ["opt.ProvisionRealFleet.L"]="Dimensiona la flotta in base al tempo di percorrenza reale (aumenta il numero di veicoli)", ["opt.ProvisionRealFleet.D"]="Dimensiona anche il numero di veicoli di ogni linea sul suo giro REALE anziché sulla stima. È questa l'opzione che comporta spese: mantenere una frequenza stretta su una linea il cui giro reale è ~2x la stima richiede circa il doppio dei veicoli, e il doppio dei costi di gestione. Disattivata (predefinita) mantiene il conteggio basato sulla stima, così una linea usa silenziosamente una frequenza effettiva più lunga di quella impostata; attivata dimensiona la flotta sul giro reale. Solo in aumento — non riduce mai una linea al di sotto della stima — e con un limite massimo, così una lettura errata non può inondarti di autobus.", ["ui.loopMeasuring"]="Il giro reale è ancora in fase di misurazione ({laps} di {need} giri).", ["ui.loopRefining"]="Giro reale di circa {real} min, ancora in affinamento ({wlaps} di {need2} giri).", ["ui.loopMeasured"]="Giro reale di {real} min, misurato ({corr}x la stima di {est} min).", ["enum.VehicleCounts.HandsOff"]="Non lasciare decidere alla mod", ["enum.VehicleCounts.ModDecides"]="Lascia decidere alla mod", ["opt.VehicleCounts.L"]="Numero di veicoli", ["opt.VehicleCounts.D"]="Chi decide quanti veicoli circolano su ogni linea con orario. \"Lascia decidere alla mod\" (consigliato) dimensiona ogni linea misurando quanto dura davvero il suo percorso, così da poter rispettare l'intervallo impostato, e non richiede attenzione. In questa modalità la mod controlla il numero su tutte le linee con orario: il cursore dei veicoli assegnati del gioco non verrà mantenuto, perché la mod riapplica il proprio valore. \"Non lasciare decidere alla mod\" restituisce tutte le linee e non tocca mai più il numero, così tu o una mod dedicata alla flotta potete gestirlo. L'attesa alla partenza funziona allo stesso modo in entrambi i casi. Se una linea chiede più veicoli di quanti ne desideri, allarga il suo intervallo; quello è il controllo vero.", ["opt.StopAtEveryStop.L"]="Ferma a ogni fermata (anche quelle vuote)", ["opt.RealisticTripsCompat.L"]="Compatibilità con Realistic Trips / tempo rallentato — attiva se usi RT o Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Disattivata per impostazione predefinita — lasciala disattivata a meno che tu non usi una mod che allunga la giornata di gioco (Time2Work / \\\"Realistic Trips\\\" o simili). Attivala con una mod di questo tipo e le partenze, gli orari di fermata e le dimensioni della flotta restano corretti anziché anticipare; la mod misura automaticamente la durata reale della giornata. Senza una mod di tempo rallentato questa impostazione non fa nulla, e se la mod ne rileva una mentre è disattivata lo segnalerà nel log. NOTA: questo percorso di compatibilità è in fase ALPHA e NON è ancora stato testato in gioco con Realistic Trips — segnala qualunque anomalia. Con Realistic Trips le tue linee useranno correttamente meno veicoli rispetto a prima.", ["opt.MorningPeakStart.L"]="Inizio picco mattutino", ["opt.MorningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco mattutino.", ["opt.MorningPeakEnd.L"]="Fine picco mattutino", ["opt.MorningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco mattutino.", ["opt.EveningPeakStart.L"]="Inizio picco serale", ["opt.EveningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco serale.", ["opt.EveningPeakEnd.L"]="Fine picco serale", ["opt.EveningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco serale.", ["opt.NightStart.L"]="Inizio notte", ["opt.NightStart.D"]="Ora in cui inizia il servizio notturno (può proseguire oltre la mezzanotte).", ["opt.NightEnd.L"]="Fine notte", ["opt.NightEnd.D"]="Ora in cui termina il servizio notturno.", ["opt.Enabled.L"]="Abilita TransitTimetables", ["grp.GroupWindows"]="Fasce di picco", ["grp.GroupCompat"]="Compatibilità", ["grp.GroupStops"]="Fermate", ["grp.GroupGeneral"]="Generale", ["ui.to"]="alle", ["ui.on"]="ATTIVO", ["ui.off"]="DISATTIVO", ["ui.otherHours"]="altre ore", ["ui.customLinePeak"]="Picco personalizzato (questa linea)", ["ui.morningPeak"]="Picco mattutino", ["ui.eveningPeak"]="Picco serale", ["ui.noLines"]="Nessuna linea serve questa fermata.", ["ui.line"]="Linea {n}", ["ui.terminusBadge"]="capolinea", ["ui.setTerminusThis"]="Imposta come capolinea", ["ui.setTerminusAll"]="Imposta come capolinea per tutte le linee qui", ["ui.buttonTooltip"]="Orari dei trasporti" },
                ["ja-JP"] = new Dictionary<string, string> { ["ui.ruleLabel"]="この停留所の乗降", ["ui.ruleBoth"]="通常", ["ui.ruleDropOff"]="降車のみ", ["ui.rulePickUp"]="乗車のみ", ["ui.ruleTechnical"]="運転停車", ["ui.ruleTechnicalNote"]="ここでは車内に乗客がいてはいけません。降車できる最後の停留所は一つ前です。この路線でこの停留所を通過する移動はできず、車両は必ず停車します。", ["ui.ruleOrphan"]="この路線には、経路上になくなった {n} 件の停留所に乗降ルールが設定されているため、適用されていません。", ["ui.ruleOrphanRemove"]="削除",["ui.arrives"]="到着: {d}", ["ui.layoverClear"]="解除", ["ui.setLayoverThis"]="第2終点に設定", ["opt.ManageVehicleCount.L"]="車両数を管理", ["opt.CleanUninstall.L"]="このセーブデータからModのデータをすべて削除", ["opt.RealisticTravelTime.L"]="リアルな移動時間（表示時刻を補正）", ["opt.RealisticTravelTime.D"]="路線の所要時間に関するゲーム内の推定値は、実際にシミュレートされる周回時間を過小評価します。バスは停留所ごとに加速・減速しますが、推定値はこれを無視しています（停留所の少ない路線で実測約1.7倍、停留所の多い路線で最大約2.5倍）。これをオンにすると、Modが各路線の実際の周回時間を計測し、リアルな停留所時刻を掲示するため、時刻表が実際のバスの動きと一致します。費用はかかりません。時刻を正確にするだけです。デフォルトはオフで、有効にするまで既存の時刻表は変更されません。", ["opt.ProvisionRealFleet.L"]="実際の移動時間に合わせて車両を配備（車両数が増加します）", ["opt.ProvisionRealFleet.D"]="各路線の車両数も、推定値ではなく実際の周回時間に合わせて算出します。費用が発生するのはこの設定です。実際の周回時間が推定値の約2倍になる路線で運行間隔を詰めて維持するには、およそ2倍の車両と2倍の維持費が必要です。オフ（デフォルト）では推定値に基づく車両数のままとなり、路線は設定した運行間隔よりも実質的に長い間隔で静かに運行されます。オンにすると実際の周回時間に合わせて配備します。増加のみ（推定値を下回って削減することはありません）で、上限も設けられているため、誤った計測値が大量のバスを送り込むことはありません。", ["ui.loopMeasuring"]="実際の所要時間を測定中です（{need} 周中 {laps} 周）。", ["ui.loopRefining"]="実際の所要時間は約 {real} 分、調整中です（{need2} 周中 {wlaps} 周）。", ["ui.loopMeasured"]="実際の所要時間は {real} 分、測定済み（推定 {est} 分の {corr} 倍）。", ["enum.VehicleCounts.HandsOff"]="Modに決めさせない", ["enum.VehicleCounts.ModDecides"]="Modに決めさせる", ["opt.VehicleCounts.L"]="車両数", ["opt.VehicleCounts.D"]="時刻表を設定した各路線が何両を走らせるかを、誰が決めるかです。「Modに決めさせる」（推奨）は、路線を一周するのに実際どれだけかかるかを計測して車両数を決め、設定した運行間隔を維持できるようにします。特に手を加える必要はありません。このモードでは、時刻表を設定したすべての路線の車両数をModが管理します。ゲーム内の割り当て車両数のスライダーは保持されません。Modが自分の値を再適用するためです。「Modに決めさせない」はすべての路線を返し、以後いっさい車両数に触れません。あなた自身または車両管理専用のModが管理できます。発車時刻までの待機動作はどちらでも同じです。ある路線が想定より多くの車両を必要とする場合は、その路線の運行間隔を広げてください。それが本来の調整方法です。", ["opt.StopAtEveryStop.L"]="すべての停留所で停車（空の停留所でも）", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 低速時間との互換性 — RT や Time2Work を使用する場合はオンに（ALPHA）", ["opt.RealisticTripsCompat.D"]="デフォルトはオフです。ゲーム内の1日を長くするMod（Time2Work / \"Realistic Trips\" など）を使用していない限り、オフのままにしてください。そのようなModと併用してこれをオンにすると、発車時刻・停留所時刻・車両数が先行せず正しく保たれます。Modが実際の1日の長さを自動的に計測します。低速時間Modがなければこの設定は何もせず、この設定がオフのときにModがそれを検出した場合はログに記録します。注意: この互換パスはALPHAであり、Realistic Trips とのゲーム内での動作検証はまだ行われていません。おかしな点があれば報告してください。Realistic Trips 使用時、路線は以前より正しく少ない車両数で運行されます。", ["opt.MorningPeakStart.L"]="朝ピークの開始", ["opt.MorningPeakStart.D"]="朝ピークの運行水準が始まる時刻。", ["opt.MorningPeakEnd.L"]="朝ピークの終了", ["opt.MorningPeakEnd.D"]="朝ピークの運行水準が終わる時刻。", ["opt.EveningPeakStart.L"]="夕ピークの開始", ["opt.EveningPeakStart.D"]="夕ピークの運行水準が始まる時刻。", ["opt.EveningPeakEnd.L"]="夕ピークの終了", ["opt.EveningPeakEnd.D"]="夕ピークの運行水準が終わる時刻。", ["opt.NightStart.L"]="夜間の開始", ["opt.NightStart.D"]="夜間運行が始まる時刻（深夜0時をまたぐ場合があります）。", ["opt.NightEnd.L"]="夜間の終了", ["opt.NightEnd.D"]="夜間運行が終わる時刻。", ["opt.Enabled.L"]="TransitTimetables を有効化", ["grp.GroupWindows"]="ピーク時間帯", ["grp.GroupCompat"]="互換性", ["grp.GroupStops"]="停留所", ["grp.GroupGeneral"]="全般", ["ui.to"]="〜", ["ui.on"]="オン", ["ui.off"]="オフ", ["ui.otherHours"]="その他の時間帯", ["ui.customLinePeak"]="カスタムピーク（この路線）", ["ui.morningPeak"]="朝ピーク", ["ui.eveningPeak"]="夕ピーク", ["ui.noLines"]="この停留所を通る路線はありません。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終点", ["ui.setTerminusThis"]="終点に設定", ["ui.setTerminusAll"]="ここのすべての路線の終点に設定", ["ui.buttonTooltip"]="Transit Timetables" },
                ["ko-KR"] = new Dictionary<string, string> { ["ui.ruleLabel"]="이 정류장의 승하차", ["ui.ruleBoth"]="일반", ["ui.ruleDropOff"]="하차 전용", ["ui.rulePickUp"]="승차 전용", ["ui.ruleTechnical"]="운전 정차", ["ui.ruleTechnicalNote"]="여기서는 아무도 차내에 있을 수 없습니다. 내릴 수 있는 마지막 정류장은 이전 정류장입니다. 이 노선에서 이 정류장을 지나는 이동은 불가능하며, 차량은 항상 정차합니다.", ["ui.ruleOrphan"]="이 노선에는 경로에서 사라진 {n}개 정류장에 승하차 규칙이 설정되어 있어 적용되지 않습니다.", ["ui.ruleOrphanRemove"]="삭제",["ui.arrives"]="도착: {d}", ["ui.layoverClear"]="해제", ["ui.setLayoverThis"]="종점 B로 설정", ["opt.ManageVehicleCount.L"]="차량 수 관리", ["opt.CleanUninstall.L"]="이 저장 파일에서 모드 데이터를 모두 제거", ["opt.RealisticTravelTime.L"]="현실적인 이동 시간 (게시 시각 보정)", ["opt.RealisticTravelTime.D"]="게임이 자체적으로 추정하는 노선 소요 시간은 실제 시뮬레이션되는 순환 시간보다 짧게 나옵니다 — 버스는 정류장마다 가속하고 제동하는데, 추정치는 이를 무시합니다 (실측 결과 정류장이 드문 노선은 약 1.7배, 정류장이 조밀한 노선은 약 2.5배까지 차이가 납니다). 이 옵션을 켜면 모드가 각 노선의 실제 순환 시간을 측정하여 현실적인 정류장 시각을 게시하므로, 시간표가 버스의 실제 운행과 일치합니다. 비용은 들지 않으며 — 시계를 정직하게 만들 뿐입니다. 기본값은 꺼짐이며, 켜기 전까지 기존 시간표는 변경되지 않습니다.", ["opt.ProvisionRealFleet.L"]="실제 이동 시간에 맞춰 차량 배치 (차량 수 증가)", ["opt.ProvisionRealFleet.D"]="추정치가 아니라 실제 순환 시간에 맞춰 각 노선의 차량 대수를 산정합니다. 비용이 드는 것은 바로 이 옵션입니다: 실제 순환 시간이 추정치의 약 2배인 노선에서 촘촘한 배차 간격을 유지하려면 차량이 약 2배, 유지비도 약 2배가 필요합니다. 꺼짐(기본값)은 추정 기반 대수를 유지하므로, 노선이 설정한 것보다 사실상 더 긴 배차 간격으로 조용히 운행됩니다. 켜면 실제 순환 시간에 맞춰 배치합니다. 증가 전용이며 — 추정치보다 노선 대수를 절대 줄이지 않습니다 — 상한이 걸려 있어 잘못된 측정값이 버스를 과도하게 늘리지 않습니다.", ["ui.loopMeasuring"]="실제 순환 시간을 측정 중입니다({need}바퀴 중 {laps}바퀴).", ["ui.loopRefining"]="실제 순환 시간은 약 {real}분이며 아직 조정 중입니다({need2}바퀴 중 {wlaps}바퀴).", ["ui.loopMeasured"]="실제 순환 시간은 {real}분으로 측정되었습니다(추정 {est}분의 {corr}배).", ["enum.VehicleCounts.HandsOff"]="모드가 결정하지 않도록", ["enum.VehicleCounts.ModDecides"]="모드가 결정하도록", ["opt.VehicleCounts.L"]="차량 수", ["opt.VehicleCounts.D"]="시간표가 설정된 각 노선이 몇 대의 차량을 운행할지 누가 결정할지 정합니다. \"모드가 결정하도록\"(권장)은 노선을 한 바퀴 도는 데 실제로 얼마나 걸리는지 측정해 차량 수를 정하므로, 설정한 배차 간격을 지킬 수 있고 따로 신경 쓸 필요가 없습니다. 이 모드에서는 시간표가 설정된 모든 노선의 차량 수를 모드가 관리합니다. 게임의 배정 차량 슬라이더는 유지되지 않습니다. 모드가 자체 값을 다시 적용하기 때문입니다. \"모드가 결정하지 않도록\"은 모든 노선을 되돌려주고 이후 차량 수에 전혀 관여하지 않으므로, 직접 또는 차량 관리 전용 모드가 담당할 수 있습니다. 출발 대기 동작은 두 경우 모두 동일합니다. 어떤 노선이 원하는 것보다 많은 차량을 요구한다면 그 노선의 배차 간격을 늘리세요. 그것이 진짜 조절 수단입니다.", ["opt.StopAtEveryStop.L"]="모든 정류장에 정차 (빈 정류장 포함)", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 느린 시간 호환 — RT나 Time2Work을 사용하면 켜세요 (알파)", ["opt.RealisticTripsCompat.D"]="기본값은 꺼짐 — 게임 내 하루 길이를 늘리는 모드(Time2Work / \"Realistic Trips\" 등)를 사용하지 않는 한 꺼진 채로 두세요. 그런 모드와 함께 이 옵션을 켜면 출발 시각, 정류장 시각, 차량 대수가 앞서 운행하지 않고 정확하게 유지됩니다. 모드가 실제 하루 길이를 자동으로 측정합니다. 느린 시간 모드가 없으면 이 설정은 아무 효과가 없으며, 이 옵션이 꺼진 상태에서 그런 모드가 감지되면 로그에 기록됩니다. 참고: 이 호환 경로는 알파이며 아직 게임 내에서 Realistic Trips와 함께 테스트되지 않았습니다 — 이상한 점이 있으면 제보해 주세요. Realistic Trips에서는 노선이 이전보다 올바르게 더 적은 차량을 사용합니다.", ["opt.MorningPeakStart.L"]="오전 첨두 시작", ["opt.MorningPeakStart.D"]="오전 첨두 운행 수준이 시작되는 시각입니다.", ["opt.MorningPeakEnd.L"]="오전 첨두 종료", ["opt.MorningPeakEnd.D"]="오전 첨두 운행 수준이 끝나는 시각입니다.", ["opt.EveningPeakStart.L"]="오후 첨두 시작", ["opt.EveningPeakStart.D"]="오후 첨두 운행 수준이 시작되는 시각입니다.", ["opt.EveningPeakEnd.L"]="오후 첨두 종료", ["opt.EveningPeakEnd.D"]="오후 첨두 운행 수준이 끝나는 시각입니다.", ["opt.NightStart.L"]="야간 시작", ["opt.NightStart.D"]="야간 운행이 시작되는 시각입니다 (자정을 넘길 수 있음).", ["opt.NightEnd.L"]="야간 종료", ["opt.NightEnd.D"]="야간 운행이 끝나는 시각입니다.", ["opt.Enabled.L"]="TransitTimetables 활성화", ["grp.GroupWindows"]="첨두 시간대", ["grp.GroupCompat"]="호환성", ["grp.GroupStops"]="정류장", ["grp.GroupGeneral"]="일반", ["ui.to"]="~", ["ui.on"]="켜짐", ["ui.off"]="꺼짐", ["ui.otherHours"]="그 외 시간", ["ui.customLinePeak"]="사용자 지정 첨두 (이 노선)", ["ui.morningPeak"]="오전 첨두", ["ui.eveningPeak"]="오후 첨두", ["ui.noLines"]="이 정류장을 지나는 노선이 없습니다.", ["ui.line"]="{n}번 노선", ["ui.terminusBadge"]="종점", ["ui.setTerminusThis"]="종점으로 설정", ["ui.setTerminusAll"]="여기의 모든 노선을 종점으로 설정", ["ui.buttonTooltip"]="Transit Timetables" },
                ["pl-PL"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Pasażerowie na tym przystanku", ["ui.ruleBoth"]="normalny", ["ui.ruleDropOff"]="tylko wysiadanie", ["ui.rulePickUp"]="tylko wsiadanie", ["ui.ruleTechnical"]="przystanek techniczny", ["ui.ruleTechnicalNote"]="Nikt nie może tu przebywać w pojeździe: ostatnia możliwość wysiadania to poprzedni przystanek. Żadna podróż tą linią nie może minąć tego przystanku, a pojazdy zawsze się tu zatrzymują.", ["ui.ruleOrphan"]="Ta linia ma reguły wsiadania/wysiadania ustawione na {n} przystanku(-ach), których nie ma już na jej trasie, więc nie są stosowane.", ["ui.ruleOrphanRemove"]="Usuń je",["ui.arrives"]="przyjazd: {d}", ["ui.layoverClear"]="usuń", ["ui.setLayoverThis"]="Ustaw jako krańcowy B", ["opt.ManageVehicleCount.L"]="Zarządzaj liczbą pojazdów", ["opt.CleanUninstall.L"]="Usuń wszystkie dane moda z tego zapisu gry", ["opt.RealisticTravelTime.L"]="Realistyczny czas przejazdu (koryguje podane godziny)", ["opt.RealisticTravelTime.D"]="Wbudowana w grę ocena czasu przejazdu linii jest zaniżona wobec rzeczywistej, symulowanej pętli — autobusy przyspieszają i hamują na każdym przystanku, czego ta ocena nie uwzględnia (zmierzone na żywo: około 1,7x na liniach z rzadkimi przystankami, do ~2,5x na liniach z gęstymi przystankami). Włącz tę opcję, a mod zmierzy rzeczywistą pętlę każdej linii i poda realistyczne godziny odjazdów, aby tablica odpowiadała temu, co faktycznie robią autobusy. Nic nie kosztuje — tylko sprawia, że zegar mówi prawdę. Domyślnie wyłączone; istniejące rozkłady jazdy pozostają bez zmian, dopóki tego nie włączysz.", ["opt.ProvisionRealFleet.L"]="Dostosuj flotę do rzeczywistego czasu przejazdu (zwiększa liczbę pojazdów)", ["opt.ProvisionRealFleet.D"]="Dobiera również liczbę pojazdów każdej linii do jej RZECZYWISTEJ pętli, a nie do szacunku. To właśnie ta opcja generuje koszty: utrzymanie krótkiego odstępu na linii, której rzeczywista pętla jest ~2x dłuższa od szacunku, wymaga około dwukrotnie więcej pojazdów i dwukrotnie wyższych kosztów utrzymania. Wyłączona (domyślnie) zachowuje liczbę pojazdów opartą na szacunku, więc linia po cichu kursuje z dłuższym faktycznym odstępem niż ustawiony; włączona dostosowuje tabor do rzeczywistej pętli. Tylko zwiększa — nigdy nie schodzi poniżej szacunku — i ma limit, więc błędny pomiar nie zaleje cię autobusami.", ["ui.loopMeasuring"]="Rzeczywisty czas obiegu jest wciąż mierzony ({laps} z {need} okrążeń).", ["ui.loopRefining"]="Rzeczywisty obieg to około {real} min, wciąż doprecyzowywany ({wlaps} z {need2} okrążeń).", ["ui.loopMeasured"]="Rzeczywisty obieg to {real} min, zmierzony ({corr}x szacunku {est} min).", ["enum.VehicleCounts.HandsOff"]="Niech mod nie decyduje", ["enum.VehicleCounts.ModDecides"]="Niech decyduje mod", ["opt.VehicleCounts.L"]="Liczba pojazdów", ["opt.VehicleCounts.D"]="Kto decyduje, ile pojazdów kursuje na każdej linii z rozkładem. \"Niech decyduje mod\" (zalecane) dobiera liczbę pojazdów, mierząc, ile naprawdę trwa pokonanie trasy, dzięki czemu linia może utrzymać ustawiony odstęp, i nie wymaga uwagi. W tym trybie mod zarządza liczbą na wszystkich liniach z rozkładem: suwak przypisanych pojazdów z gry nie zostanie zachowany, ponieważ mod ponownie stosuje własną wartość. \"Niech mod nie decyduje\" zwraca wszystkie linie i nigdy więcej nie rusza liczby, więc ty lub dedykowany mod flotowy możecie nią zarządzać. Wstrzymywanie odjazdów działa tak samo w obu przypadkach. Jeśli linia potrzebuje więcej pojazdów, niż chcesz, zwiększ jej odstęp; to jest właściwe pokrętło.", ["opt.StopAtEveryStop.L"]="Zatrzymuj na każdym przystanku (nawet pustym)", ["opt.RealisticTripsCompat.L"]="Zgodność z Realistic Trips / spowolnionym czasem — włącz, jeśli używasz RT lub Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Domyślnie wyłączone — zostaw wyłączone, chyba że używasz moda wydłużającego dobę w grze (Time2Work / \"Realistic Trips\" lub podobnego). Włącz z takim modem, a odjazdy, godziny na przystankach i wielkości taboru pozostaną poprawne zamiast kursować przed czasem; mod automatycznie mierzy rzeczywistą długość doby. Bez moda spowalniającego czas to ustawienie nic nie robi, a jeśli mod wykryje taki mod, gdy ta opcja jest wyłączona, odnotuje to w dzienniku. UWAGA: ta ścieżka zgodności jest w wersji ALPHA i NIE została jeszcze przetestowana z Realistic Trips w grze — zgłaszaj wszelkie nieprawidłowości. Pod Realistic Trips twoje linie będą poprawnie używać mniej pojazdów niż wcześniej.", ["opt.MorningPeakStart.L"]="Początek porannego szczytu", ["opt.MorningPeakStart.D"]="Godzina, o której zaczyna się poranny poziom obsługi szczytowej.", ["opt.MorningPeakEnd.L"]="Koniec porannego szczytu", ["opt.MorningPeakEnd.D"]="Godzina, o której kończy się poranny poziom obsługi szczytowej.", ["opt.EveningPeakStart.L"]="Początek wieczornego szczytu", ["opt.EveningPeakStart.D"]="Godzina, o której zaczyna się wieczorny poziom obsługi szczytowej.", ["opt.EveningPeakEnd.L"]="Koniec wieczornego szczytu", ["opt.EveningPeakEnd.D"]="Godzina, o której kończy się wieczorny poziom obsługi szczytowej.", ["opt.NightStart.L"]="Początek nocy", ["opt.NightStart.D"]="Godzina, o której zaczyna się obsługa nocna (może przekraczać północ).", ["opt.NightEnd.L"]="Koniec nocy", ["opt.NightEnd.D"]="Godzina, o której kończy się obsługa nocna.", ["opt.Enabled.L"]="Włącz TransitTimetables", ["grp.GroupWindows"]="Okna szczytu", ["grp.GroupCompat"]="Zgodność", ["grp.GroupStops"]="Przystanki", ["grp.GroupGeneral"]="Ogólne", ["ui.to"]="do", ["ui.on"]="WŁ.", ["ui.off"]="WYŁ.", ["ui.otherHours"]="pozostałe godziny", ["ui.customLinePeak"]="Własny szczyt (ta linia)", ["ui.morningPeak"]="Poranny szczyt", ["ui.eveningPeak"]="Wieczorny szczyt", ["ui.noLines"]="Żadna linia nie obsługuje tego przystanku.", ["ui.line"]="Linia {n}", ["ui.terminusBadge"]="krańcowy", ["ui.setTerminusThis"]="Ustaw jako krańcowy", ["ui.setTerminusAll"]="Ustaw jako krańcowy dla wszystkich linii tutaj", ["ui.buttonTooltip"]="Rozkłady jazdy komunikacji" },
                ["pt-BR"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Passageiros aqui", ["ui.ruleBoth"]="normal", ["ui.ruleDropOff"]="somente desembarque", ["ui.rulePickUp"]="somente embarque", ["ui.ruleTechnical"]="parada técnica", ["ui.ruleTechnicalNote"]="Ninguém pode estar a bordo aqui: a última parada para descer é a anterior. Nenhuma viagem nesta linha pode passar desta parada, e os veículos sempre param.", ["ui.ruleOrphan"]="Esta linha tem regras de embarque/desembarque em {n} parada(s) que não estão mais na sua rota, portanto não são aplicadas.", ["ui.ruleOrphanRemove"]="Remover",["ui.arrives"]="chega: {d}", ["ui.layoverClear"]="remover", ["ui.setLayoverThis"]="Definir como terminal B", ["opt.ManageVehicleCount.L"]="Gerenciar o número de veículos", ["opt.CleanUninstall.L"]="Remover todos os dados do mod deste jogo salvo", ["opt.RealisticTravelTime.L"]="Tempo de viagem realista (corrige os horários exibidos)", ["opt.RealisticTravelTime.D"]="A própria estimativa do jogo sobre quanto tempo uma linha leva subestima o trajeto real simulado — os ônibus aceleram e freiam em cada parada, algo que a estimativa ignora (medido ao vivo em cerca de 1,7x em linhas com poucas paradas e até ~2,5x nas com muitas paradas). Ative esta opção e o mod mede o trajeto real de cada linha e exibe horários de parada realistas, para que o quadro corresponda ao que os ônibus realmente fazem. Não custa nada — só torna o relógio honesto. Desativado por padrão; as tabelas de horários existentes não mudam até você ativá-lo.", ["opt.ProvisionRealFleet.L"]="Dimensionar a frota pelo tempo de viagem real (aumenta o número de veículos)", ["opt.ProvisionRealFleet.D"]="Também dimensiona a quantidade de veículos de cada linha pelo trajeto REAL em vez da estimativa. Esta é a opção que gasta: manter um intervalo curto em uma linha cujo trajeto real é ~2x a estimativa exige cerca do dobro de veículos, e o dobro de manutenção. Desativado (padrão) mantém a contagem baseada na estimativa, então uma linha roda silenciosamente com um intervalo efetivo maior do que você definiu; ativado dimensiona para o trajeto real. Apenas cresce — nunca reduz uma linha abaixo da estimativa — e é limitado, para que uma leitura ruim não inunde você de ônibus.", ["ui.loopMeasuring"]="O percurso real ainda está sendo medido ({laps} de {need} voltas).", ["ui.loopRefining"]="Percurso real de cerca de {real} min, ainda sendo ajustado ({wlaps} de {need2} voltas).", ["ui.loopMeasured"]="Percurso real de {real} min, medido ({corr}x a estimativa de {est} min).", ["enum.VehicleCounts.HandsOff"]="Não deixar o mod decidir", ["enum.VehicleCounts.ModDecides"]="Deixar o mod decidir", ["opt.VehicleCounts.L"]="Número de veículos", ["opt.VehicleCounts.D"]="Quem decide quantos veículos cada linha com horário opera. \"Deixar o mod decidir\" (recomendado) dimensiona cada linha medindo quanto tempo o percurso realmente leva, para que ela consiga manter o intervalo definido, e não exige atenção. Nesse modo o mod controla o número em todas as linhas com horário: o controle de veículos atribuídos do jogo não será mantido, porque o mod reaplica o próprio valor. \"Não deixar o mod decidir\" devolve todas as linhas e nunca mais mexe no número, para que você ou um mod dedicado a frotas possa cuidar disso. As esperas de partida funcionam igual nos dois casos. Se uma linha pedir mais veículos do que você quer, aumente o intervalo dela; esse é o controle de verdade.", ["opt.StopAtEveryStop.L"]="Parar em cada parada (mesmo nas vazias)", ["opt.RealisticTripsCompat.L"]="Compatibilidade com Realistic Trips / tempo lento — ative se você usa RT ou Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desativado por padrão — deixe desativado a menos que você use um mod que alongue o dia do jogo (Time2Work / \"Realistic Trips\" ou similar). Ative-o com um mod desses e as partidas, horários de parada e tamanhos de frota permanecem corretos em vez de rodar adiantados; o mod mede automaticamente a duração real do dia. Sem um mod de tempo lento esta configuração não faz nada, e se o mod detectar um enquanto isto estiver desativado ele registrará no log. NOTA: este caminho de compatibilidade é ALFA e ainda NÃO foi testado com o Realistic Trips em jogo — por favor, relate qualquer coisa estranha. Sob o Realistic Trips suas linhas usarão corretamente menos veículos do que antes.", ["opt.MorningPeakStart.L"]="Início do pico da manhã", ["opt.MorningPeakStart.D"]="Hora em que começa o nível de serviço do pico da manhã.", ["opt.MorningPeakEnd.L"]="Fim do pico da manhã", ["opt.MorningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da manhã.", ["opt.EveningPeakStart.L"]="Início do pico da noite", ["opt.EveningPeakStart.D"]="Hora em que começa o nível de serviço do pico da noite.", ["opt.EveningPeakEnd.L"]="Fim do pico da noite", ["opt.EveningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da noite.", ["opt.NightStart.L"]="Início da madrugada", ["opt.NightStart.D"]="Hora em que começa o serviço noturno (pode passar da meia-noite).", ["opt.NightEnd.L"]="Fim da madrugada", ["opt.NightEnd.D"]="Hora em que termina o serviço noturno.", ["opt.Enabled.L"]="Ativar TransitTimetables", ["grp.GroupWindows"]="Janelas de pico", ["grp.GroupCompat"]="Compatibilidade", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="Geral", ["ui.to"]="às", ["ui.on"]="LIGADO", ["ui.off"]="DESLIGADO", ["ui.otherHours"]="outros horários", ["ui.customLinePeak"]="Pico personalizado (esta linha)", ["ui.morningPeak"]="Pico da manhã", ["ui.eveningPeak"]="Pico da noite", ["ui.noLines"]="Nenhuma linha atende esta parada.", ["ui.line"]="Linha {n}", ["ui.terminusBadge"]="terminal", ["ui.setTerminusThis"]="Definir como terminal", ["ui.setTerminusAll"]="Definir como terminal para todas as linhas aqui", ["ui.buttonTooltip"]="Tabelas de Horários do Transporte" },
                ["ru-RU"] = new Dictionary<string, string> { ["ui.ruleLabel"]="Пассажиры здесь", ["ui.ruleBoth"]="обычная", ["ui.ruleDropOff"]="только высадка", ["ui.rulePickUp"]="только посадка", ["ui.ruleTechnical"]="техническая остановка", ["ui.ruleTechnicalNote"]="Здесь никто не может находиться в салоне: последняя возможность выйти — предыдущая остановка. Ни одна поездка по этой линии не может пройти через эту остановку, а транспорт всегда останавливается.", ["ui.ruleOrphan"]="У этой линии заданы правила посадки/высадки на {n} остановке(-ах), которых больше нет на её маршруте, поэтому они не применяются.", ["ui.ruleOrphanRemove"]="Удалить",["ui.arrives"]="прибытие: {d}", ["ui.layoverClear"]="убрать", ["ui.setLayoverThis"]="Назначить конечной Б", ["opt.ManageVehicleCount.L"]="Управлять количеством транспорта", ["opt.CleanUninstall.L"]="Удалить все данные мода из этого сохранения", ["opt.RealisticTravelTime.L"]="Реалистичное время в пути (корректировка расписания)", ["opt.RealisticTravelTime.D"]="Собственная оценка игры о продолжительности маршрута занижает реальный, смоделированный круг — автобусы разгоняются и тормозят на каждой остановке, что оценка не учитывает (замерено вживую примерно 1,7x на редких маршрутах и до ~2,5x на маршрутах с частыми остановками). Включите этот параметр, и мод замерит реальный круг каждого маршрута и покажет реалистичное время на остановках, чтобы табло совпадало с тем, что автобусы делают на самом деле. Ничего не стоит — просто делает часы честными. По умолчанию ВЫКЛ; существующие расписания не меняются, пока вы это не включите.", ["opt.ProvisionRealFleet.L"]="Планировать парк по реальному времени в пути (увеличивает число транспортных средств)", ["opt.ProvisionRealFleet.D"]="Также рассчитывать количество транспорта каждого маршрута по РЕАЛЬНОМУ кругу, а не по оценке. Именно этот параметр тратит деньги: удержание плотного интервала на маршруте, чей реальный круг ~2x от оценки, требует примерно вдвое больше транспорта и вдвое больше расходов на содержание. ВЫКЛ (по умолчанию) сохраняет количество по оценке, поэтому маршрут незаметно ходит с более длинным фактическим интервалом, чем вы задали; ВКЛ планирует под реальный круг. Только увеличивает — никогда не урезает маршрут ниже оценки — и ограничено, так что ошибочный замер не завалит вас автобусами.", ["ui.loopMeasuring"]="Реальное время круга ещё измеряется ({laps} из {need} кругов).", ["ui.loopRefining"]="Реальное время круга около {real} мин, уточняется ({wlaps} из {need2} кругов).", ["ui.loopMeasured"]="Реальное время круга {real} мин, измерено ({corr}x от оценки в {est} мин).", ["enum.VehicleCounts.HandsOff"]="Пусть мод не решает", ["enum.VehicleCounts.ModDecides"]="Пусть решает мод", ["opt.VehicleCounts.L"]="Количество транспорта", ["opt.VehicleCounts.D"]="Кто определяет, сколько машин работает на каждой линии с расписанием. \"Пусть решает мод\" (рекомендуется) подбирает количество, измеряя, сколько на самом деле занимает круг линии, чтобы она выдерживала заданный интервал, и не требует внимания. В этом режиме мод управляет количеством на всех линиях с расписанием: игровой ползунок назначенных машин не сохранится, поскольку мод заново применяет собственное значение. \"Пусть мод не решает\" возвращает все линии и больше никогда не трогает количество, так что им можете управлять вы или специализированный мод. Задержка отправления работает одинаково в обоих случаях. Если линия требует больше машин, чем вам хотелось бы, увеличьте её интервал; это и есть настоящий рычаг.", ["opt.StopAtEveryStop.L"]="Останавливаться на каждой остановке (даже пустой)", ["opt.RealisticTripsCompat.L"]="Совместимость с Realistic Trips / замедлением времени — включите, если используете RT или Time2Work (АЛЬФА)", ["opt.RealisticTripsCompat.D"]="По умолчанию ВЫКЛ — оставьте выключенным, если только вы не используете мод, удлиняющий игровой день (Time2Work / \\\"Realistic Trips\\\" или подобный). Включите его вместе с таким модом, и отправления, время на остановках и размеры парка останутся корректными вместо опережения; мод автоматически замеряет реальную длину дня. Без мода замедления времени этот параметр ничего не делает, а если мод обнаружит такой при выключенном параметре, он отметит это в журнале. ПРИМЕЧАНИЕ: этот путь совместимости — АЛЬФА и пока НЕ тестировался с Realistic Trips в игре — сообщайте обо всём странном. При Realistic Trips ваши маршруты будут корректно использовать меньше транспорта, чем раньше.", ["opt.MorningPeakStart.L"]="Начало утреннего часа пик", ["opt.MorningPeakStart.D"]="Час, когда начинается уровень обслуживания утреннего часа пик.", ["opt.MorningPeakEnd.L"]="Конец утреннего часа пик", ["opt.MorningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания утреннего часа пик.", ["opt.EveningPeakStart.L"]="Начало вечернего часа пик", ["opt.EveningPeakStart.D"]="Час, когда начинается уровень обслуживания вечернего часа пик.", ["opt.EveningPeakEnd.L"]="Конец вечернего часа пик", ["opt.EveningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания вечернего часа пик.", ["opt.NightStart.L"]="Начало ночи", ["opt.NightStart.D"]="Час, когда начинается ночное обслуживание (может переходить за полночь).", ["opt.NightEnd.L"]="Конец ночи", ["opt.NightEnd.D"]="Час, когда заканчивается ночное обслуживание.", ["opt.Enabled.L"]="Включить TransitTimetables", ["grp.GroupWindows"]="Окна часа пик", ["grp.GroupCompat"]="Совместимость", ["grp.GroupStops"]="Остановки", ["grp.GroupGeneral"]="Общие", ["ui.to"]="до", ["ui.on"]="ВКЛ", ["ui.off"]="ВЫКЛ", ["ui.otherHours"]="прочие часы", ["ui.customLinePeak"]="Свой час пик (этот маршрут)", ["ui.morningPeak"]="Утренний час пик", ["ui.eveningPeak"]="Вечерний час пик", ["ui.noLines"]="Эту остановку не обслуживают маршруты.", ["ui.line"]="Маршрут {n}", ["ui.terminusBadge"]="конечная", ["ui.setTerminusThis"]="Назначить конечной", ["ui.setTerminusAll"]="Назначить конечной для всех маршрутов здесь", ["ui.buttonTooltip"]="Расписания транспорта" },
                ["zh-HANS"] = new Dictionary<string, string> { ["ui.ruleLabel"]="此站乘降", ["ui.ruleBoth"]="正常", ["ui.ruleDropOff"]="仅下客", ["ui.rulePickUp"]="仅上客", ["ui.ruleTechnical"]="技术停车", ["ui.ruleTechnicalNote"]="此站车内不得载客：最后可下车的站为前一站。本线路的任何行程都无法通过此站，车辆始终停靠。", ["ui.ruleOrphan"]="该线路在 {n} 个已不在其路线上的站点设置了乘降规则，因此未生效。", ["ui.ruleOrphanRemove"]="移除",["ui.arrives"]="到站：{d}", ["ui.layoverClear"]="移除", ["ui.setLayoverThis"]="设为第二终点站", ["opt.ManageVehicleCount.L"]="管理车辆数量", ["opt.CleanUninstall.L"]="移除本存档中的所有模组数据", ["opt.RealisticTravelTime.L"]="真实旅行时间（修正显示的时刻）", ["opt.RealisticTravelTime.D"]="游戏自身对线路运行时长的估算低于真实模拟的环线用时——公交车在每一站都要加速和刹车，而估算忽略了这一点（实测中，站点稀疏的线路约为 1.7 倍，站点密集的线路可达约 2.5 倍）。开启此项后，模组会测量每条线路的真实环线用时并给出真实的到站时刻，使显示牌与公交车实际运行相符。此项不产生任何花费——它只是让时刻表如实反映现实。默认关闭；在你启用之前，现有时刻表保持不变。", ["opt.ProvisionRealFleet.L"]="根据实际行驶时间配置车队（增加车辆数量）", ["opt.ProvisionRealFleet.D"]="同时按每条线路的真实环线用时（而非估算值）来确定其车辆数量。这一项会产生花费：要在真实环线约为估算值 2 倍的线路上维持紧凑的发车间隔，大约需要两倍的车辆和两倍的维护费。关闭（默认）沿用基于估算的车辆数，导致线路实际运行的发车间隔悄悄比你设定的更长；开启则按真实环线配备车辆。只增不减——绝不会把线路的车辆减到估算值以下——并且有上限，因此一次错误的读数不会让公交车泛滥成灾。", ["ui.loopMeasuring"]="正在测量实际环行时间（已完成 {laps}/{need} 圈）。", ["ui.loopRefining"]="实际环行时间约 {real} 分钟，仍在校准（已完成 {wlaps}/{need2} 圈）。", ["ui.loopMeasured"]="实际环行时间为 {real} 分钟，已测得（为 {est} 分钟估算值的 {corr} 倍）。", ["enum.VehicleCounts.HandsOff"]="不让模组决定", ["enum.VehicleCounts.ModDecides"]="让模组决定", ["opt.VehicleCounts.L"]="车辆数量", ["opt.VehicleCounts.D"]="由谁决定每条已设置时刻表的线路运行多少车辆。「让模组决定」（推荐）通过测量线路实际跑完一圈需要多久来配置车辆，使其能够维持你设定的发车间隔，无需额外关注。在此模式下，模组会掌管所有已设置时刻表线路的车辆数量：游戏自带的分配车辆滑块不会保留，因为模组会重新应用自己的数值。「不让模组决定」会交还所有线路，此后不再改动车辆数量，便于你自己或专门的车队模组接管。两种模式下的发车等待行为完全相同。如果某条线路所需的车辆超出你的预期，请调宽该线路的发车间隔，那才是真正的调节手段。", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使无人的站点）", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 慢时间兼容——若使用 RT 或 Time2Work 请开启（ALPHA）", ["opt.RealisticTripsCompat.D"]="默认关闭——除非你使用了会延长游戏内一天时长的模组（Time2Work / \"Realistic Trips\" 或类似模组），否则请保持关闭。搭配此类模组时开启，发车时间、到站时刻和车辆数量将保持正确而不会提前运行；模组会自动测量真实的一天时长。若未使用慢时间模组，此设置不起任何作用；若在此项关闭时检测到该类模组，将会在日志中记录提示。注意：此兼容路径为 ALPHA，尚未在游戏内针对 Realistic Trips 测试——如有异常请反馈。在 Realistic Trips 下，你的线路将正确地使用比以往更少的车辆。", ["opt.MorningPeakStart.L"]="早高峰开始", ["opt.MorningPeakStart.D"]="早高峰运营水平开始的时刻。", ["opt.MorningPeakEnd.L"]="早高峰结束", ["opt.MorningPeakEnd.D"]="早高峰运营水平结束的时刻。", ["opt.EveningPeakStart.L"]="晚高峰开始", ["opt.EveningPeakStart.D"]="晚高峰运营水平开始的时刻。", ["opt.EveningPeakEnd.L"]="晚高峰结束", ["opt.EveningPeakEnd.D"]="晚高峰运营水平结束的时刻。", ["opt.NightStart.L"]="夜间开始", ["opt.NightStart.D"]="夜间运营开始的时刻（可能跨过午夜）。", ["opt.NightEnd.L"]="夜间结束", ["opt.NightEnd.D"]="夜间运营结束的时刻。", ["opt.Enabled.L"]="启用 TransitTimetables", ["grp.GroupWindows"]="高峰时段", ["grp.GroupCompat"]="兼容性", ["grp.GroupStops"]="站点", ["grp.GroupGeneral"]="常规", ["ui.to"]="至", ["ui.on"]="开", ["ui.off"]="关", ["ui.otherHours"]="其他时段", ["ui.customLinePeak"]="自定义高峰（本线路）", ["ui.morningPeak"]="早高峰", ["ui.eveningPeak"]="晚高峰", ["ui.noLines"]="没有线路停靠此站点。", ["ui.line"]="线路 {n}", ["ui.terminusBadge"]="终点站", ["ui.setTerminusThis"]="设为终点站", ["ui.setTerminusAll"]="设为此处所有线路的终点站", ["ui.buttonTooltip"]="公交时刻表" },
                ["zh-HANT"] = new Dictionary<string, string> { ["ui.ruleLabel"]="此站乘降", ["ui.ruleBoth"]="正常", ["ui.ruleDropOff"]="僅下客", ["ui.rulePickUp"]="僅上客", ["ui.ruleTechnical"]="技術停車", ["ui.ruleTechnicalNote"]="此站車內不得載客：最後可下車的站為前一站。本線路的任何行程都無法通過此站，車輛始終停靠。", ["ui.ruleOrphan"]="該線路在 {n} 個已不在其路線上的站點設置了乘降規則，因此未生效。", ["ui.ruleOrphanRemove"]="移除",["ui.arrives"]="抵達：{d}", ["ui.layoverClear"]="移除", ["ui.setLayoverThis"]="設為第二終點站", ["opt.ManageVehicleCount.L"]="管理車輛數量", ["opt.CleanUninstall.L"]="從此存檔移除所有模組資料", ["opt.RealisticTravelTime.L"]="真實旅行時間（校正發車時刻表）", ["opt.RealisticTravelTime.D"]="遊戲本身對一條路線所需時間的估算，低估了真實模擬的環線 —— 公車在每一站都要加速與煞車，而估算忽略了這一點（實測站點稀疏的路線約為 1.7 倍，站點密集的路線最高可達約 2.5 倍）。開啟此選項後，模組會實測每條路線的真實環線時間，並張貼真實的靠站時刻，讓時刻表符合公車實際的運行情況。不花任何費用 —— 它只是讓時鐘變得誠實。預設為關閉；在你啟用之前，既有的時刻表維持不變。", ["opt.ProvisionRealFleet.L"]="根據實際行駛時間配置車隊（增加車輛數量）", ["opt.ProvisionRealFleet.D"]="同時依每條路線的「真實」環線時間（而非估算值）來配置車輛數。這是會花錢的選項：要在真實環線約為估算 2 倍的路線上維持緊密班距，需要約兩倍的車輛，也需要兩倍的維護費。關閉（預設）維持以估算為準的車輛數，因此路線實際運行的有效班距會悄悄比你設定的更長；開啟則按真實環線配置。只增不減 —— 絕不會把某條路線的車輛降到估算值以下 —— 並設有上限，因此一次錯誤的讀數不會讓你被公車淹沒。", ["ui.loopMeasuring"]="正在測量實際環行時間（已完成 {laps}/{need} 圈）。", ["ui.loopRefining"]="實際環行時間約 {real} 分鐘，仍在校準（已完成 {wlaps}/{need2} 圈）。", ["ui.loopMeasured"]="實際環行時間為 {real} 分鐘，已測得（為 {est} 分鐘估算值的 {corr} 倍）。", ["enum.VehicleCounts.HandsOff"]="不讓模組決定", ["enum.VehicleCounts.ModDecides"]="讓模組決定", ["opt.VehicleCounts.L"]="車輛數量", ["opt.VehicleCounts.D"]="由誰決定每條已設定時刻表的路線運行多少車輛。「讓模組決定」（建議）透過測量路線實際跑完一圈需要多久來配置車輛，使其能夠維持你設定的發車間隔，無需額外關注。在此模式下，模組會掌管所有已設定時刻表路線的車輛數量：遊戲內建的指派車輛滑桿不會保留，因為模組會重新套用自己的數值。「不讓模組決定」會交還所有路線，此後不再改動車輛數量，方便你自己或專門的車隊模組接管。兩種模式下的發車等待行為完全相同。如果某條路線所需的車輛超出你的預期，請調寬該路線的發車間隔，那才是真正的調節手段。", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使空無一人）", ["opt.RealisticTripsCompat.L"]="Realistic Trips／慢速時間相容性 —— 若你使用 RT 或 Time2Work 請開啟（ALPHA）", ["opt.RealisticTripsCompat.D"]="預設為關閉 —— 除非你使用會延長遊戲內一天長度的模組（Time2Work／「Realistic Trips」或類似模組），否則請保持關閉。搭配這類模組時開啟，發車時刻、靠站時刻與車隊規模便會維持正確而不會提早運行；模組會自動實測真實的一天長度。若沒有慢速時間模組，此設定不會有任何作用；而若模組偵測到有這類模組但此設定為關閉，它會在日誌中註記。注意：此相容路徑仍為 ALPHA，尚未在遊戲中對 Realistic Trips 進行測試 —— 若有任何異常請回報。在 Realistic Trips 下，你的路線會正確地使用比以往更少的車輛。", ["opt.MorningPeakStart.L"]="早尖峰開始", ["opt.MorningPeakStart.D"]="早尖峰服務等級開始的時刻。", ["opt.MorningPeakEnd.L"]="早尖峰結束", ["opt.MorningPeakEnd.D"]="早尖峰服務等級結束的時刻。", ["opt.EveningPeakStart.L"]="晚尖峰開始", ["opt.EveningPeakStart.D"]="晚尖峰服務等級開始的時刻。", ["opt.EveningPeakEnd.L"]="晚尖峰結束", ["opt.EveningPeakEnd.D"]="晚尖峰服務等級結束的時刻。", ["opt.NightStart.L"]="夜間開始", ["opt.NightStart.D"]="夜間服務開始的時刻（可能跨越午夜）。", ["opt.NightEnd.L"]="夜間結束", ["opt.NightEnd.D"]="夜間服務結束的時刻。", ["opt.Enabled.L"]="啟用 TransitTimetables", ["grp.GroupWindows"]="尖峰時段", ["grp.GroupCompat"]="相容性", ["grp.GroupStops"]="站點", ["grp.GroupGeneral"]="一般", ["ui.to"]="至", ["ui.on"]="開啟", ["ui.off"]="關閉", ["ui.otherHours"]="其他時段", ["ui.customLinePeak"]="自訂尖峰（此路線）", ["ui.morningPeak"]="早尖峰", ["ui.eveningPeak"]="晚尖峰", ["ui.noLines"]="沒有路線行經此站。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終點站", ["ui.setTerminusThis"]="設為終點站", ["ui.setTerminusAll"]="設為此處所有路線的終點站", ["ui.buttonTooltip"]="運輸時刻表" },
        };
    }
